 function staffView(){const club=team.club;const effects={'Assistant coach':'Improves the captain’s leadership growth.','Batting coach':'Adds batting development when you train a player.','Bowling coach':'Adds bowling development when you train a player.','Fielding coach':'Adds fielding development when you train a player.','Fitness coach':'Supports overall player development plans.','Physio':'Shortens injury recovery by up to two appearances.'};return <>{card(<>{txt('CLUB STAFF',styles.eyebrow)}{txt('Build your backroom team',styles.title)}{txt('Each role is filled. Replacing a staff member costs a one-off appointment fee and raises the role rating; the new wage is included in your season accounts.',styles.muted)}{row('ANNUAL STAFF WAGES',money(Object.values(club.staff).reduce((n,p)=>n+p.annualWage,0)))}</>)}{E.STAFF_ROLES_LIST.map(role=>{const p=club.staff[role],cost=Math.max(0,(p.rating-49)*9000);return card(<>{txt(role.toUpperCase(),styles.eyebrow)}{row(p.name,`RATING ${p.rating}`)}{txt(`${effects[role]} Annual wage: ${money(p.annualWage)}.`,styles.muted)}{button(`Appoint stronger ${role.toLowerCase()} · ${money(cost)}`,()=>update(c=>E.improveStaff(c,role)),true,!!m||p.rating>=95||club.balance<cost)}</>,role);})}</>;}
